with with_gaps as (select *, case when lag(started_at) over (partition by browser order by started_at, id) is null or started_at > lag(started_at) over (partition by browser order by started_at, id) + interval 30 days then 1 else 0 end as is_new_burst from sessions), sessions_sessions as (select *, sum(is_new_burst) over (partition by browser order by started_at, id rows between unbounded preceding and current row) as island_id from with_gaps) select date_trunc('week', started_at) as week_start, device, round(avg(island_id), 2) as avg_island_id, max(started_at) as last_started_at, count(case when browser = 'Chrome' then 1 end) as chrome_count, round(sum(is_new_burst) / nullif(count(case when browser = 'Safari' then 1 end), 0), 2) as is_new_burst_per_safari from sessions_sessions group by rollup (date_trunc('week', started_at), device) order by avg_island_id nulls last;
